fn directive(kind: v1::DirectiveKind, payload: agent_directive::Payload) -> AgentDirective {
    AgentDirective {
        kind: kind as i32,
        payload: Some(payload),
        ..AgentDirective::default()
    }
}

#[test]
fn typed_directives_map_to_their_advertised_capabilities() {
    let cases = [
        (
            directive(
                v1::DirectiveKind::Notify,
                agent_directive::Payload::Notify(v1::NotifyDirective {
                    message: "notice".to_string(),
                }),
            ),
            DirectiveRequirement {
                capability: SupervisorDirectiveCapability::Notify,
                required_capability: "notify.v1",
            },
        ),
        (
            directive(
                v1::DirectiveKind::Prompt,
                agent_directive::Payload::Prompt(v1::PromptDirective {
                    instruction: "follow the bounded context".to_string(),
                }),
            ),
            DirectiveRequirement {
                capability: SupervisorDirectiveCapability::Prompt,
                required_capability: "prompt.v1",
            },
        ),
        (
            directive(
                v1::DirectiveKind::Assign,
                agent_directive::Payload::Assign(v1::AssignDirective {}),
            ),
            DirectiveRequirement {
                capability: SupervisorDirectiveCapability::Assign,
                required_capability: "assign.v1",
            },
        ),
        (
            directive(
                v1::DirectiveKind::Steer,
                agent_directive::Payload::Steer(v1::SteerDirective {
                    instruction: "change objective safely".to_string(),
                    checkpoint_required: true,
                }),
            ),
            DirectiveRequirement {
                capability: SupervisorDirectiveCapability::Steer,
                required_capability: "steer.v1",
            },
        ),
        (
            directive(
                v1::DirectiveKind::Pause,
                agent_directive::Payload::Pause(v1::PauseDirective {
                    checkpoint_required: true,
                }),
            ),
            DirectiveRequirement {
                capability: SupervisorDirectiveCapability::Pause,
                required_capability: "pause.v1",
            },
        ),
        (
            directive(
                v1::DirectiveKind::Resume,
                agent_directive::Payload::Resume(v1::ResumeDirective {}),
            ),
            DirectiveRequirement {
                capability: SupervisorDirectiveCapability::Resume,
                required_capability: "resume.v1",
            },
        ),
        (
            directive(
                v1::DirectiveKind::Drain,
                agent_directive::Payload::Drain(v1::DrainDirective {
                    deadline: "2030-01-01T00:00:00Z".to_string(),
                }),
            ),
            DirectiveRequirement {
                capability: SupervisorDirectiveCapability::Drain,
                required_capability: "drain.v1",
            },
        ),
        (
            directive(
                v1::DirectiveKind::Terminate,
                agent_directive::Payload::Terminate(v1::TerminateDirective {
                    mode: v1::TerminationMode::Graceful as i32,
                    graceful_deadline: "2030-01-01T00:00:00Z".to_string(),
                }),
            ),
            DirectiveRequirement {
                capability: SupervisorDirectiveCapability::TerminateGracefully,
                required_capability: "terminate.graceful.v1",
            },
        ),
        (
            directive(
                v1::DirectiveKind::Terminate,
                agent_directive::Payload::Terminate(v1::TerminateDirective {
                    mode: v1::TerminationMode::ForceAfterDeadline as i32,
                    graceful_deadline: "2030-01-01T00:00:00Z".to_string(),
                }),
            ),
            DirectiveRequirement {
                capability: SupervisorDirectiveCapability::TerminateForce,
                required_capability: "terminate.force.v1",
            },
        ),
    ];

    for (directive, expected) in cases {
        assert_eq!(directive_requirement(&directive), Some(expected));
    }
}

#[test]
fn directive_requirement_refuses_unknown_and_mismatched_wire_shapes() {
    let mismatched = directive(
        v1::DirectiveKind::Pause,
        agent_directive::Payload::Resume(v1::ResumeDirective {}),
    );
    let unspecified = AgentDirective::default();

    assert_eq!(directive_requirement(&mismatched), None);
    assert_eq!(directive_requirement(&unspecified), None);
}

#[test]
fn directive_payload_digest_binds_the_closed_kind_and_payload() {
    let assign = directive(
        v1::DirectiveKind::Assign,
        agent_directive::Payload::Assign(v1::AssignDirective {}),
    );
    let resume = directive(
        v1::DirectiveKind::Resume,
        agent_directive::Payload::Resume(v1::ResumeDirective {}),
    );
    let mismatched = directive(
        v1::DirectiveKind::Pause,
        agent_directive::Payload::Resume(v1::ResumeDirective {}),
    );

    assert_eq!(
        directive_payload_digest(&assign),
        directive_payload_digest(&assign)
    );
    assert_ne!(
        directive_payload_digest(&assign),
        directive_payload_digest(&resume)
    );
    assert_eq!(directive_payload_digest(&mismatched), None);
}
